# Compute Z(p^a) = number of n in [0, p^a - 1] with p^a | N(n)
# Using recurrence N(n) = n*N(n-1) + 1 mod p^a

def Z(pa, p):
    """Count n in [0, pa-1] with N(n) ≡ 0 mod pa"""
    N = 1  # N(0) = 1
    count = 0
    if N % pa == 0:
        count += 1
    for n in range(1, pa):
        N = (n * N + 1) % pa
        if N == 0:
            count += 1
    return count

for p in [2, 3, 5, 7, 11, 13, 17, 19, 23]:
    print(f"p={p}:")
    for a in range(1, 8):
        pa = p**a
        if pa > 10**7:
            break
        z = Z(pa, p)
        print(f"  Z({p}^{a}={pa}) = {z}")
